namespace sv_e11db30bcdac41229e5011f865f806bc.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@using sv_e11db30bcdac41229e5011f865f806bc.Services

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div class="product-name">@Product.Name</div>
    <div class="product-price">@Product.Price.ToString("C")</div>
    <div class="product-rating" title="@($"{Product.Rating:F1} out of 5")">
        @for (int i = 1; i <= 5; i++)
        {
            @(i <= (int)Math.Round(Product.Rating) ? "★" : "☆")
        }
    </div>
    @if (!Product.InStock)
    {
        <span class="out-of-stock-badge">Out of Stock</span>
    }
    <button class="add-to-cart-btn"
            disabled="@(!Product.InStock)"
            @onclick="HandleAddToCart"
            @onclick:stopPropagation="true">
        Add to Cart
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick() => await OnSelected.InvokeAsync(Product);

    private async Task HandleAddToCart() => await OnAddToCart.InvokeAsync(Product);
}

.product-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 1rem;
    cursor: pointer;
    transition: box-shadow 0.2s;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.product-image {
    background: #f0f0f0;
    height: 180px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
    margin-bottom: 0.75rem;
    color: #999;
    font-size: 0.9rem;
    text-align: center;
    padding: 0.5rem;
}

.product-name {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.product-price {
    font-size: 1.2rem;
    color: #2d8a4e;
    font-weight: 700;
    margin-bottom: 0.25rem;
}

.product-rating {
    color: #f5a623;
    margin-bottom: 0.5rem;
}

.out-of-stock-badge {
    background: #dc3545;
    color: white;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-size: 0.8rem;
    display: inline-block;
    margin-bottom: 0.5rem;
    align-self: flex-start;
}

.add-to-cart-btn {
    width: 100%;
    padding: 0.5rem;
    border: none;
    background: #0d6efd;
    color: white;
    border-radius: 4px;
    cursor: pointer;
    margin-top: auto;
    font-size: 0.95rem;
}

.add-to-cart-btn:hover:not(:disabled) {
    background: #0b5ed7;
}

.add-to-cart-btn:disabled {
    background: #6c757d;
    cursor: not-allowed;
}

@using sv_e11db30bcdac41229e5011f865f806bc.Services

<div class="product-grid">
    @foreach (var product in Products)
    {
        <ProductCard Product="product"
                     OnSelected="OnProductSelected"
                     OnAddToCart="OnAddToCart" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = [];

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 1.25rem;
}

@using sv_e11db30bcdac41229e5011f865f806bc.Services

<aside class="sidebar">
    <h3>Filters</h3>

    <div class="filter-section">
        <h4>Category</h4>
        @foreach (var category in Categories)
        {
            <label class="category-item">
                <input type="checkbox"
                       checked="@selectedCategories.Contains(category)"
                       @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                @category
            </label>
        }
    </div>

    <div class="filter-section">
        <h4>Price Range</h4>
        <div class="price-inputs">
            <input type="number" placeholder="Min" min="0" step="0.01"
                   value="@minPrice" @onchange="e => minPrice = ParseDecimal(e.Value)" />
            <input type="number" placeholder="Max" min="0" step="0.01"
                   value="@maxPrice" @onchange="e => maxPrice = ParseDecimal(e.Value)" />
        </div>
    </div>

    <div class="filter-section">
        <label class="category-item">
            <input type="checkbox" @bind="inStockOnly" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnApplyFilters { get; set; }

    [Parameter]
    public EventCallback OnClearFilters { get; set; }

    private HashSet<string> selectedCategories = [];
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );
        await OnApplyFilters.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        await OnClearFilters.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

.sidebar {
    background: #f8f9fa;
    padding: 1.25rem;
    border-radius: 8px;
}

.sidebar h3 {
    margin-top: 0;
    margin-bottom: 1rem;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h4 {
    font-size: 0.95rem;
    margin-bottom: 0.5rem;
    margin-top: 0;
}

.category-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
}

.price-inputs {
    display: flex;
    gap: 0.5rem;
}

.price-inputs input {
    width: 50%;
    padding: 0.35rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

.filter-actions {
    display: flex;
    gap: 0.5rem;
}

.filter-actions button {
    flex: 1;
    padding: 0.5rem;
    border-radius: 4px;
    border: 1px solid #ccc;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-apply {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd !important;
}

.btn-apply:hover {
    background: #0b5ed7;
}

.btn-clear {
    background: white;
}

.btn-clear:hover {
    background: #e9ecef;
}

.toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 4px;
}

.toolbar select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    margin-left: 0.5rem;
}

.showing-label {
    color: #666;
    font-size: 0.9rem;
}

.pagination {
    display: flex;
    justify-content: center;
    gap: 0.25rem;
    margin-top: 1.5rem;
    flex-wrap: wrap;
}

.pagination button {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    background: white;
    cursor: pointer;
    font-size: 0.9rem;
}

.pagination button:hover:not(:disabled):not(.active) {
    background: #e9ecef;
}

.pagination button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.pagination button.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

