{"path": "/tmp/sv-e11db30bcdac41229e5011f865f806bc/Components/Catalog/CatalogPagination.razor", "file_text": "<nav class="pagination" aria-label="Product catalog pages">
    <button disabled="@(Page <= 1)" @onclick="() => GoToPage(Page - 1)">Previous</button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="@(pageNum == Page ? "active" : "")"
                @onclick="() => GoToPage(pageNum)">
            @pageNum
        </button>
    }

    <button disabled="@(Page >= TotalPages)" @onclick="() => GoToPage(Page + 1)">Next</button>
</nav>

@code {
    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; } = 1;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
            await OnPageChanged.InvokeAsync(page);
    }
}
"}

