+@page "/catalog"
+@using sv_e11db30bcdac41229e5011f865f806bc.Components.Catalog
+@using sv_e11db30bcdac41229e5011f865f806bc.Services
+@rendermode InteractiveServer
+@inject IProductService ProductService
+
+<PageTitle>Product Catalog</PageTitle>
+
+<h1>Product Catalog</h1>
+
+@if (errorMessage is not null)
+{
+    <div class="error-banner">
+        <p>⚠ @errorMessage</p>
+        <button @onclick="LoadProducts">Retry</button>
+    </div>
+}
+else
+{
+    <div class="catalog-layout">
+        <div class="catalog-sidebar">
+            <CatalogSidebar Categories="categories"
+                            OnApplyFilters="HandleApplyFilters"
+                            OnClearFilters="HandleClearFilters" />
+        </div>
+
+        <div class="catalog-main">
+            <CatalogToolbar SortBy="@sortBy"
+                            TotalCount="@totalCount"
+                            Page="@currentPage"
+                            PageSize="@pageSize"
+                            OnSortChanged="HandleSortChanged" />
+
+            @if (isLoading)
+            {
+                <div class="loading-indicator">
+                    <p>Loading products…</p>
+                </div>
+            }
+            else if (products.Count == 0)
+            {
+                <div class="empty-state">
+                    <p>No products match your criteria. Try adjusting your filters.</p>
+                </div>
+            }
+            else
+            {
+                <ProductGrid Products="products"
+                             OnProductSelected="HandleProductSelected"
+                             OnAddToCart="HandleAddToCart" />
+
+                @if (totalPages > 1)
+                {
+                    <CatalogPagination Page="@currentPage"
+                                       TotalPages="@totalPages"
+                                       OnPageChanged="HandlePageChanged" />
+                }
+            }
+        </div>
+    </div>
+}
+
+@code {
+    private List<Product> products = [];
+    private List<string> categories = [];
+    private ProductFilter currentFilter = new(null, null, null, false);
+    private string sortBy = "price_asc";
+    private int currentPage = 1;
+    private int totalCount;
+    private int totalPages;
+    private const int pageSize = 12;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
+
+            await Task.WhenAll(categoriesTask, productsTask);
+
+            categories = categoriesTask.Result;
+            ApplyResult(productsTask.Result);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load catalog: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task LoadProducts()
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            var result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
+            ApplyResult(result);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load products: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void ApplyResult(PagedResult<Product> result)
+    {
+        products = result.Items;
+        totalCount = result.TotalCount;
+        totalPages = (int)Math.Ceiling((double)result.TotalCount / pageSize);
+    }
+
+    private async Task HandleApplyFilters(ProductFilter filter)
+    {
+        currentFilter = filter;
+        currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandleClearFilters()
+    {
+        currentFilter = new ProductFilter(null, null, null, false);
+        currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandleSortChanged(string? newSort)
+    {
+        if (newSort is not null)
+        {
+            sortBy = newSort;
+            currentPage = 1;
+            await LoadProducts();
+        }
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        currentPage = page;
+        await LoadProducts();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder for cart integration
+        return Task.CompletedTask;
+    }
+}
+

toolArgs.file_text:
.catalog-layout {
    display: flex;
    gap: 1.5rem;
    align-items: flex-start;
}

.catalog-sidebar {
    width: 25%;
    min-width: 220px;
    flex-shrink: 0;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.loading-indicator {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 200px;
    color: #666;
    font-size: 1.1rem;
}

.empty-state {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 200px;
    color: #666;
    font-size: 1.1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.error-banner {
    background: #f8d7da;
    color: #842029;
    padding: 1rem 1.5rem;
    border-radius: 8px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.error-banner p {
    margin: 0;
}

.error-banner button {
    padding: 0.4rem 1rem;
    border: 1px solid #842029;
    background: white;
    color: #842029;
    border-radius: 4px;
    cursor: pointer;
}

.error-banner button:hover {
    background: #f1aeb5;
}

